const frontendStatus = $('Validar Frontend BR').first().json;
const backendStatus = $('Validar Backend BR').first().json;
const himalayasStatus = $('Validar Himalayas').first().json;
const front = frontendStatus.sucesso ? frontendStatus.vagas : [];
const back = backendStatus.sucesso ? backendStatus.vagas : [];
const remoteResponse = himalayasStatus.sucesso ? {jobs:himalayasStatus.vagas} : {jobs:[]};
const fontes = [frontendStatus,backendStatus,himalayasStatus];
const falhas = fontes.filter(s=>!s.sucesso);
if (falhas.length) console.log('[MonitoramentoVagas] Falha(s): '+JSON.stringify(falhas.map(s=>({fonte:s.fonte, statusHTTP:s.statusHTTP, mensagem:s.mensagem, retryAfterSegundos:s.retryAfterSegundos}))));
const githubFile = $input.first().json;
if (!githubFile.sha || !githubFile.content) throw new Error('Arquivo data/vagas.json não encontrado no repositório. Publique o site primeiro.');
const previous = JSON.parse(Buffer.from(githubFile.content.replace(/\s/g, ''), 'base64').toString('utf8'));
const current = Array.isArray(previous.vagas) ? previous.vagas : [];
if (falhas.length === fontes.length) { console.log('[MonitoramentoVagas] Todas as fontes falharam: histórico preservado, nenhuma publicação.'); return [{json:{changed:false,total:current.length,novos:0,erroFontes:true}}]; }
const now = Date.now();
const maxAgeMs = 90 * 86400000;
const recentLimit = 60 * 86400000;
const reDev = /desenvolv|developer|programador|programming|engenheir[oa] de software|software engineer|front.?end|back.?end|full.?stack|python|javascript|typescript|react|node\.?js|qa|testes|quality assurance|est[aá]gio.*(ti|tecnologia|sistemas)/i;
const reEntry = /\b(junior|júnior|jr\.?|est[aá]gio|estagi[aá]ri[oa]|intern(ship)?|trainee|entry[ -]?level|sem experi[eê]ncia|primeiro emprego|aprendiz)\b/i;
const reSenior = /\b(senior|s[eê]nior|sr\.?|lead|principal|staff|manager|gerente|arquiteto|architect|pleno|mid[ -]?level)\b/i;
function text(html) { return String(html ?? '').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); }
function dateISO(t) { if(!t) return ''; const n = Number(t); const d = new Date(Number.isFinite(n) && n > 100000000 ? n*1000 : t); return isNaN(d.getTime()) ? '' : d.toISOString(); }
function level(s) { if (/est[aá]gio|estagi|intern/i.test(s)) return 'Estágio'; if (/trainee|aprendiz/i.test(s)) return 'Trainee'; return 'Júnior'; }
function fromIssues(arr, source) {
  return arr.flatMap(v => {
    if (!v || !v.id || v.pull_request || v.state !== 'open') return [];
    const labels = Array.isArray(v.labels) ? v.labels.map(l => l.name || '').join(' ') : '';
    const title = String(v.title || ''); const description = text(v.body || '');
    if (!reDev.test(title + ' ' + labels + ' ' + description.slice(0,700))) return [];
    if (!reEntry.test(title + ' ' + labels + ' ' + description.slice(0,2000)) || reSenior.test(title + ' ' + labels)) return [];
    const published = dateISO(v.created_at);
    if (published && now - new Date(published).getTime() > recentLimit) return [];
    return [{id: source.toLowerCase().replace(/\W/g,'-')+'-'+v.id, cargo:title, empresa:'Ver anúncio', nivel:level(title+' '+labels+' '+description.slice(0,500)), modalidade:/remot|home.office/i.test(title+' '+labels+' '+description)?'Remoto':(/h[ií]brid/i.test(title+' '+labels+' '+description)?'Híbrido':'Não informada'), local:'Brasil / ver anúncio', descricao:description.slice(0,450), publicadoEm:published, fonte:source, link:v.html_url, capturadoEm:new Date(now).toISOString()}];
  });
}
function fromHimalayas(jobs) {
  return jobs.flatMap(v => {
    const title=String(v.title||''); const seniority=String(v.seniority||''); const type=String(v.employmentType||'');
    if (!reDev.test(title) || reSenior.test(title)) return [];
    if (!(reEntry.test(title+' '+seniority+' '+type) || /entry[ -]?level/i.test(seniority))) return [];
    if (!v.guid || !v.applicationLink) return [];
    const location=Array.isArray(v.locationRestrictions)?v.locationRestrictions:[];
    if (location.length && !location.some(c=>/brazil|brasil|^br$/i.test(typeof c==='string'?c:(c.name||c.code||'')))) return [];
    return [{id:'himalayas-'+v.guid, cargo:title, empresa:v.companyName||'Não informada', nivel:level(title+' '+seniority+' '+type), modalidade:'Remoto', local:location.length?'Brasil':'Mundial (ver restrições)', descricao:text(v.excerpt||v.description).slice(0,450), publicadoEm:dateISO(v.pubDate), expiraEm:dateISO(v.expiryDate), fonte:'Himalayas', link:v.applicationLink, capturadoEm:new Date(now).toISOString()}];
  });
}
const remoteJobs=Array.isArray(remoteResponse.jobs)?remoteResponse.jobs:[];
const incoming=[...fromIssues(front,'Frontend BR'),...fromIssues(back,'Backend BR'),...fromHimalayas(remoteJobs)];
const map = new Map(current.filter(v => v && v.id && (falhas.length > 0 || ((!v.expiraEm || new Date(v.expiraEm).getTime()>now) && (!v.publicadoEm || now-new Date(v.publicadoEm).getTime()<maxAgeMs)))).map(v => [v.id,v]));
for (const v of incoming) {
  const old=map.get(v.id);
  // Preserva a data original de captura e evita mudanças cosméticas a cada hora
  map.set(v.id, old ? {...old,...v,capturadoEm:old.capturadoEm||v.capturadoEm} : v);
}
let vagas=[...map.values()].sort((a,b)=>String(b.publicadoEm||'').localeCompare(String(a.publicadoEm||''))).slice(0,400);
const normal = list=>JSON.stringify(list.map(({capturadoEm,...rest})=>rest));
const changed=normal(vagas)!==normal(current);
if(!changed) return [{json:{changed:false, total:vagas.length, novos:0}}];
const oldIds=new Set(current.map(v=>v.id));
const updated={atualizadoEm:new Date(now).toISOString(),total:vagas.length,vagas};
return [{json:{changed:true,total:vagas.length,novos:vagas.filter(v=>!oldIds.has(v.id)).length,sha:githubFile.sha,content:Buffer.from(JSON.stringify(updated,null,2)+'\n','utf8').toString('base64')}}];

const fonte = "Frontend BR";
const tipo = "github";
const entradas = $input.all().map(i => i.json);
const consultadoEm = new Date().toISOString();
let status = null, headers = {}, body, mensagem = '', sucesso = false;
function textoErro(v) {
  if (typeof v === 'string') return v.slice(0, 500);
  if (v && typeof v === 'object') return String(v.message || v.error || v.errors?.[0]?.message || JSON.stringify(v)).slice(0, 500);
  return String(v ?? '').slice(0, 500);
}
if (entradas.length && entradas.every(e => e && typeof e.statusCode === 'number')) {
  status = entradas[0].statusCode; headers = entradas[0].headers || {};
  body = entradas.length === 1 ? entradas[0].body : entradas.flatMap(e => Array.isArray(e.body) ? e.body : [e.body]);
  if (!entradas.every(e=>e.statusCode===status)) { status = null; mensagem='Resposta inconsistente: códigos HTTP diferentes na mesma consulta.'; }
} else if (entradas.some(e => e?.error || e?.message)) {
  mensagem = textoErro(entradas.find(e => e?.error || e?.message)?.error || entradas.find(e => e?.message)?.message);
} else {
  // Fallback for n8n versions returning the body directly.
  body = entradas.length > 1 ? entradas : entradas[0];
  status = 200;
}
let vagas = [];
if (status >= 200 && status < 300) {
  if (tipo === 'github') {
    if (Array.isArray(body)) { vagas = body; sucesso = true; }
    else if (body && typeof body === 'object' && body.id && body.title) { vagas = [body]; sucesso = true; }
    else mensagem = 'Resposta com estrutura inesperada: esperado array de issues.';
  } else {
    if (body && typeof body === 'object' && Array.isArray(body.jobs)) { vagas = body.jobs; sucesso = true; }
    else mensagem = 'Resposta com estrutura inesperada: esperado objeto com jobs[].';
  }
} else if (!mensagem) {
  const descricao = ({401:'Não autorizado',403:'Acesso proibido ou limite da API',404:'Endpoint não encontrado',429:'Limite de requisições'}[status]) || (status >= 500 ? 'Erro temporário do servidor' : 'Falha HTTP');
  mensagem = descricao + ' (HTTP ' + String(status ?? 'desconhecido') + '): ' + textoErro(body);
}
const h = Object.fromEntries(Object.entries(headers || {}).map(([k,v])=>[k.toLowerCase(),v]));
const retryAfter = h['retry-after'] ?? null;
let retryAfterSegundos = null;
if (retryAfter !== null) {
  const n = Number(retryAfter);
  if (Number.isFinite(n) && n >= 0) retryAfterSegundos = Math.ceil(n);
  else { const d = Date.parse(String(retryAfter)); if (!isNaN(d)) retryAfterSegundos = Math.max(0, Math.ceil((d - Date.now()) / 1000)); }
}
const estado = sucesso ? (vagas.length ? 'ok' : 'sem_vagas') : 'falhou';
const diagnostico = {fonte, consultadoEm, statusHTTP:status, estado, quantidade:vagas.length, mensagem:sucesso?'':mensagem, retryAfterSegundos};
console.log('[MonitoramentoVagas] '+JSON.stringify(diagnostico));
return [{json:{...diagnostico, sucesso, vagas}}];

